import sys
from math import gcd

# ---------- prime factorization ----------
LIMIT = 31623

def sieve(limit):
    is_p = [True] * (limit + 1)
    is_p[0] = is_p[1] = False
    for i in range(2, int(limit ** 0.5) + 1):
        if is_p[i]:
            step = i
            start = i * i
            for j in range(start, limit + 1, step):
                is_p[j] = False
    return [i for i in range(2, limit + 1) if is_p[i]]

SMALL_PRIMES = sieve(LIMIT)
factor_cache = {}

def is_prime(n):
    if n < 2:
        return False
    if n % 2 == 0:
        return n == 2
    if n % 3 == 0:
        return n == 3
    if n % 5 == 0:
        return n == 5
    if n % 7 == 0:
        return n == 7

    d = n - 1
    s = 0
    while d % 2 == 0:
        s += 1
        d //= 2

    for a in (2, 3, 5, 7):
        if a >= n:
            continue
        x = pow(a, d, n)
        if x == 1 or x == n - 1:
            continue
        for _ in range(s - 1):
            x = (x * x) % n
            if x == n - 1:
                break
        else:
            return False
    return True

def get_primes(n):
    res = factor_cache.get(n)
    if res is not None:
        return res

    if is_prime(n):
        res = (n,)
        factor_cache[n] = res
        return res

    tmp = n
    res = []
    for p in SMALL_PRIMES:
        if p * p > tmp:
            break
        if tmp % p == 0:
            res.append(p)
            while tmp % p == 0:
                tmp //= p
            if tmp > 1 and is_prime(tmp):
                res.append(tmp)
                tmp = 1
                break

    if tmp > 1:
        res.append(tmp)

    res = tuple(res)
    factor_cache[n] = res
    return res

# ---------- segment tree merge ----------
THRESHOLD = 64

def cross_count(suff, pref):
    m = len(suff)
    n = len(pref)
    if m == 0 or n == 0:
        return 0

    if m * n <= THRESHOLD:
        total = 0
        for g1, c1 in suff:
            for g2, c2 in pref:
                if gcd(g1, g2) > 1:
                    total += c1 * c2
        return total

    B = {}
    for g, c in pref:
        for p in get_primes(g):
            B[p] = B.get(p, 0) + c

    total = 0
    for g, c in suff:
        best = 0
        for p in get_primes(g):
            val = B.get(p, 0)
            if val > best:
                best = val
        total += c * best
    return total

def merge(L, R):
    if L[1] == 0:
        return R
    if R[1] == 0:
        return L

    lans, lwhole, lpref, lsuff = L
    rans, rwhole, rpref, rsuff = R

    ans = lans + rans + cross_count(lsuff, rpref)
    whole = gcd(lwhole, rwhole)

    # prefixes
    if lwhole > 1 and rpref:
        first = rpref[0][0]
        if gcd(lwhole, first) > 1:
            pref = list(lpref)
            for g, c in rpref:
                ng = gcd(lwhole, g)
                if ng <= 1:
                    break
                if pref and pref[-1][0] == ng:
                    last = pref[-1]
                    pref[-1] = (ng, last[1] + c)
                else:
                    pref.append((ng, c))
        else:
            pref = lpref
    else:
        pref = lpref

    # suffixes
    if rwhole > 1 and lsuff:
        first = lsuff[0][0]
        if gcd(first, rwhole) > 1:
            suff = list(rsuff)
            for g, c in lsuff:
                ng = gcd(g, rwhole)
                if ng <= 1:
                    break
                if suff and suff[-1][0] == ng:
                    last = suff[-1]
                    suff[-1] = (ng, last[1] + c)
                else:
                    suff.append((ng, c))
        else:
            suff = rsuff
    else:
        suff = rsuff

    return (ans, whole, pref, suff)

# ---------- main ----------
def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    it = iter(data)
    N = next(it)
    M = next(it)

    arr = [next(it) for _ in range(N)]

    size = N
    tree = [None] * (2 * size)
    EMPTY = (0, 0, [], [])

    def make_leaf(v):
        if v > 1:
            return (1, v, [(v, 1)], [(v, 1)])
        else:
            return (0, v, [], [])

    for i, v in enumerate(arr):
        tree[size + i] = make_leaf(v)

    for i in range(size - 1, 0, -1):
        tree[i] = merge(tree[2 * i], tree[2 * i + 1])

    out = []

    for _ in range(M):
        T = next(it)
        A = next(it)
        B = next(it)

        if T == 1:
            pos = A - 1
            v = B
            idx = size + pos
            tree[idx] = make_leaf(v)
            idx //= 2
            while idx:
                tree[idx] = merge(tree[2 * idx], tree[2 * idx + 1])
                idx //= 2
        else:
            l = A - 1
            r = B - 1

            L = l + size
            R = r + 1 + size

            resL = EMPTY
            resR = EMPTY

            while L < R:
                if L & 1:
                    resL = merge(resL, tree[L])
                    L += 1
                if R & 1:
                    R -= 1
                    resR = merge(tree[R], resR)
                L //= 2
                R //= 2

            res = merge(resL, resR)
            out.append(str(res[0]))

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()
